37	// check は、opts の行が全量の起点からレビューした内容まで変わっていないかを確認する。
38	// 入力の誤り (解決できない版・レビューした内容に無いファイルや行) は error で返し、結果にしない。
39	func check(opts options) (result, error) {
40		if err := checkGitVersion(opts.worktree); err != nil {
41			return result{}, err
42		}
43		top, err := toplevel(opts.root)
44		if err != nil {
45			return result{}, err
46		}
47		g := gitRunner{root: top}
48	
49		base, found, err := g.commit(opts.base)
50		if err != nil {
51			return result{}, err
52		} else if !found {
53			return result{}, inputf("-base をコミットに解決できません: %s", opts.base)
54		}
55		targetName := opts.rev
56		if opts.worktree {
57			targetName = "HEAD"
58		}
59		target, found, err := g.commit(targetName)
60		if err != nil {
61			return result{}, err
62		} else if !found {
63			return result{}, inputf("レビューした内容のコミット (%s) を解決できません", targetName)
64		}
65	
66		// 全量の起点がレビューした内容のコミットと同じなら、範囲 <起点>..<コミット> が空になり、
67		// コミット済みのどの行も起点にあったままと報告される。ブランチの変更と前からある行を区別できない。
68		// フラグ -allow-same-commit (判定ノード D9) では、起点は前の指摘を判定した回のコミットで、
69		// 確認するのは、そのコミットからレビューした内容までに行が変わっていないかである。同じコミットなら、
70		// コミット済みの行は起点にあったままなので、確認できないとせずに、下の確認 (シンボリックリンク・
71		// 属性・コミットしていない変更) に進む。その後の結果の決め方は、git blame の手前の分岐に書く。
72		if base == target && !opts.allowSameCommit {
73			return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) と同じで、このブランチの変更と前からある行を区別できない", short(base), targetName)}, nil
74		}
75		ok, err := g.isAncestor(base, target)
76		if err != nil {
77			return result{}, asRun(err)
78		}
79		if !ok {
80			return result{kind: unverifiable, reason: fmt.Sprintf("全量の起点 %s が、レビューした内容のコミット (%s) の祖先ではない", short(base), targetName)}, nil
81		}
82	
83		// 指摘の file は、レビューした内容にあるはず (根拠の照合 E1 を通っている)。無ければ入力の誤り。
84		targetEntry, err := g.entry(target, opts.file)
85		if err != nil {
86			return result{}, err
87		}
88		if opts.worktree {
89			st, err := os.Stat(filepath.Join(top, filepath.FromSlash(opts.file)))
90			if err != nil || !st.Mode().IsRegular() {
91				return result{}, inputf("作業ツリーに -file のファイルがありません: %s", opts.file)
92			}
93		} else if targetEntry != entryFile && targetEntry != entrySymlink {
94			return result{}, inputf("レビューした内容 (%s) に -file のファイルがありません: %s", opts.rev, opts.file)
95		}
96	
97		if baseEntry, err := g.entry(base, opts.file); err != nil {
98			return result{}, err
99		} else if baseEntry != entryFile && baseEntry != entrySymlink {
100			return result{kind: notHolds, reason: fmt.Sprintf("全量の起点 %s に同じパスのファイルが無い (このブランチで作った・改名した・移したファイル)", short(base))}, nil
101		}
102		if opts.worktree && targetEntry != entryFile && targetEntry != entrySymlink {
103			return result{kind: notHolds, reason: "HEAD に同じパスのファイルが無い (コミットしていないファイル)"}, nil
104		}
105	
106		// 次の 3 つは、レビュアが読む内容とコマンド git blame が見る内容が違いうる。シンボリックリンクと clean
107		// フィルタは行番号が対応せず、属性 ident は行の中の書き換えを、比べる前の変換で戻す。どれも書き換えた行が
108		// 起点のままと報告されうる (誤った holds) ので、方式によらず確認しない。
109		// git はシンボリックリンクのリンクの文字列を 1 行のブロブとして記録し、git blame もそれを見るが、
110		// レビュアはリンクの先の内容を読む
111		if targetEntry == entrySymlink {
112			return result{kind: unverifiable, reason: "指摘のファイルが追跡中のシンボリックリンクで、レビュアが読むリンクの先の内容と、git が記録するリンクの文字列の行番号が対応しない"}, nil
113		}
114		// clean フィルタは、作業ツリーの内容 (レビュアが読む、フィルタの前の内容) を変換してから記録し、
115		// git blame もフィルタの後の内容 (コミットの内容と、オプション --contents で渡した内容) を見る。フィルタが
116		// 行を増やしたり消したりすると、行番号がずれる。属性 ident は、記録するときに「$Id: … $」を「$Id$」へ戻し、
117		// コマンド git hash-object --path と git blame --contents も同じ変換を当ててから比べるので、「$Id: … $」の
118		// 中の書き換えが見えない。-rev では、コミットしていない変更の確認より前に、属性 filter と ident を調べる (その確認が実行する
119		// git hash-object --path が、フィルタのプログラムを実行しないように)
120		attr, err := g.convertingAttribute(opts.file)
121		if err != nil {
122			return result{}, err
123		}
124		switch attr {
125		case "filter":
126			return result{kind: unverifiable, reason: "指摘のファイルに clean フィルタ (属性 filter) が設定されていて、作業ツリーの内容 (フィルタの前) と、git blame が見るフィルタの後の内容の行番号がずれうる"}, nil
127		case "ident":
128			return result{kind: unverifiable, reason: "指摘のファイルに属性 ident が設定されていて、git は「$Id: … $」の中を「$Id$」へ戻してから内容を比べるので、レビュアが読んだその中の書き換えを確認できない"}, nil
129		}
130	
131		if !opts.worktree {
132			// 結果のファイルで受け取ったレビューは、共有の作業ツリーでコミットしていない変更を見た可能性があり、
133			// 結果のファイルからは分からない。ほかのファイルの変更は、指摘の file の行番号を変えないので見ない。
134			// 比べる相手は HEAD ではなく、レビューした内容のコミットにする。-rev が HEAD より前なら、レビューの
135			// 時点ではコミットしていなかった編集が、その後のコミットに入っていることがあり、HEAD と比べても見つからない
136			changed, err := g.hasUncommittedChange(top, target, targetEntry, opts.file)
137			if err != nil {
138				return result{}, asRun(err)
139			}
140			if changed {
141				return result{kind: unverifiable, reason: fmt.Sprintf("指摘のファイルの作業ツリーかインデックスの内容が、レビューした内容のコミット (%s) と違う (コミットしていない変更があるか、そのコミットより後のコミットで変わった) ので、レビューがどの内容を見たかが分からない", targetName)}, nil
142			}
143		}
144	
145		if base == target && !opts.worktree {
146			// ここに来るのは、フラグ -allow-same-commit を付けて、-rev に起点と同じコミットを渡したときだけ。
147			// 範囲 <起点>..<起点> には起点でないコミットが無く、git blame はこの範囲を渡されると、HEAD を親として
148			// 作業ツリーの内容を調べる。-rev が HEAD と違うと、結果が判定の時点の HEAD で変わる。レビューした内容は
149			// 起点のコミットそのもので、指摘のファイルにコミットしていない変更が無いことも上で確認したので、
150			// git blame を実行せずに、どの行も起点にあったままとする。-worktree のときは、レビューした内容の
151			// コミットが HEAD なので、下の git blame が HEAD を親として作業ツリーの内容を調べるのが正しい。
152			return sameCommitResult(g, base, target, opts)
153		}
154	
155		blamed, err := g.blame(base, target, opts)
156		if err != nil {
157			return result{}, err
158		}
159		return classify(base, opts.file, blamed), nil
160	}
161	
162	// sameCommitResult は、起点とレビューした内容が同じコミットのときの結果を返す。レビューした内容の
163	// どの行も、起点の同じ行番号の行である。行がレビューした内容の行数を越えるのは、git blame を実行する
164	// ときと同じく入力の誤りにする。
165	func sameCommitResult(g gitRunner, base, target string, opts options) (result, error) {
166		n, err := g.lineCount(target, opts)
167		if err != nil {
168			return result{}, err
169		}
170		if err := checkLastLine(opts, n); err != nil {
171			return result{}, err
172		}
173		res := result{kind: holds, reason: fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))}
174		for _, r := range opts.ranges {
175			for line := r.from; line <= r.to; line++ {
176				res.lines = append(res.lines, lineResult{line: line, kind: holds, note: fmt.Sprintf("全量の起点にあったまま (起点の %d 行目)", line)})
177			}
178		}
179		return res, nil
180	}
181	
182	// checkLastLine は、渡した行がレビューした内容の行数 n を越えないかを確認する。越えるのは渡し方の誤り。
183	func checkLastLine(opts options, n int) error {
184		if last := opts.ranges[len(opts.ranges)-1].to; last > n {
185			return inputf("行 %d が、レビューした内容の -file の行数 (%d) を越えます", last, n)
186		}
187		return nil
188	}
189	
190	// classify は blame の結果を行ごとに分類し、全体の結果を決める。
191	// 成り立たない行が 1 つでもあれば成り立たない、無くて確認できない行があれば確認できない。
192	func classify(base, file string, blamed []blameLine) result {
193		res := result{kind: holds}
194		for _, b := range blamed {
195			l := lineResult{line: b.final}
196			switch {
197			case isZero(b.commit):
198				l.kind, l.note = notHolds, "コミットしていない行"
199			case !b.boundary:
200				l.kind, l.note = notHolds, fmt.Sprintf("全量の起点より後のコミット %s が書いた・書き換えた行", short(b.commit))
201			case b.commit != base:
202				// 起点より前に分かれた履歴をマージすると、行がその分岐点まで遡り、そこが境界になる。
203				// その行が起点にもあったかは、この結果からは決められない。
204				l.kind, l.note = unverifiable, fmt.Sprintf("全量の起点を通らない履歴 (起点より前に分かれた履歴のマージなど) から来た行で、境界のコミットが %s。全量の起点にあったかを決められない", short(b.commit))
205			case b.filename != file:
206				l.kind, l.note = notHolds, fmt.Sprintf("このブランチで改名・移動したファイルの行 (全量の起点では %s)", b.filename)
207			default:
208				// 境界が起点でパスも同じなので、フィールド orig は起点のファイルでの行番号
209				l.kind, l.note = holds, fmt.Sprintf("全量の起点にあったまま (起点の %d 行目)", b.orig)
210			}
211			res.lines = append(res.lines, l)
212			switch {
213			case l.kind == notHolds:
214				res.kind = notHolds
215			case l.kind == unverifiable && res.kind == holds:
216				res.kind = unverifiable
217			}
218		}
219		switch res.kind {
220		case notHolds:
221			res.reason = "対象の行のうち、全量の起点から変わった行がある"
222		case unverifiable:
223			res.reason = "対象の行のうち、全量の起点にあったかを決められない行がある"
224		default:
225			res.reason = fmt.Sprintf("対象の行はどれも、全量の起点 %s にあったまま変わっていない", short(base))
226		}
227		return res
228	}
229	
230	// lineCount は、レビューした内容の -file の行数を返す。数え方は git blame と同じで、
231	// 末尾に改行の無い最後の行も 1 行と数える。
232	func (g gitRunner) lineCount(target string, opts options) (int, error) {
233		var content []byte
234		if opts.worktree {
235			b, err := os.ReadFile(filepath.Join(g.root, filepath.FromSlash(opts.file)))
236			if err != nil {
237				return 0, runf("作業ツリーの -file を読めません: %v", err)
238			}
239			content = b
240		} else {
241			out, _, err := g.run("cat-file", "-p", target+":"+opts.file)
242			if err != nil {
243				return 0, asRun(err)
244			}
245			content = []byte(out)
246		}
247		n := bytes.Count(content, []byte("\n"))
248		if len(content) > 0 && content[len(content)-1] != '\n' {
249			n++
250		}
251		return n, nil
252	}
253	
254	type blameLine struct {
255		orig     int    // その行を最後に変えたコミット (範囲の外なら境界のコミット) の内容での行番号
256		final    int    // レビューした内容での行番号
257		commit   string // その行を最後に変えたコミット。範囲の外なら境界のコミット
258		boundary bool   // 範囲 <起点>..<コミット> の境界のコミットか
259		filename string // そのコミットでのパス
260	}
261	
262	var blameHeader = regexp.MustCompile(`^([0-9a-f]{40}|[0-9a-f]{64}) ([0-9]+) ([0-9]+)( [0-9]+)?$`)
263	
264	// parsePorcelain は git blame --line-porcelain の出力を読む。
265	func parsePorcelain(out string) ([]blameLine, error) {
266		var lines []blameLine
267		var cur *blameLine
268		for _, s := range strings.Split(out, "\n") {
269			if cur == nil {
270				if s == "" {
271					continue
272				}
273				m := blameHeader.FindStringSubmatch(s)
274				if m == nil {
275					return nil, fmt.Errorf("git blame の出力を読めません: %q", s)
276				}
277				orig, _ := strconv.Atoi(m[2])
278				final, _ := strconv.Atoi(m[3])
279				cur = &blameLine{orig: orig, final: final, commit: m[1]}
280				continue
281			}
282			switch {
283			case strings.HasPrefix(s, "\t"):
284				if cur.filename == "" {
285					return nil, fmt.Errorf("git blame の出力に行 %d のファイル名がありません", cur.final)
286				}
287				lines = append(lines, *cur)
288				cur = nil
289			case s == "boundary":
290				cur.boundary = true
291			case strings.HasPrefix(s, "filename "):
292				name, err := unquotePath(strings.TrimPrefix(s, "filename "))
293				if err != nil {
294					return nil, err
295				}
296				cur.filename = name
297			}
298		}
299		if cur != nil {
300			return nil, fmt.Errorf("git blame の出力が行 %d の途中で途切れています", cur.final)
301		}
302		return lines, nil
303	}
304	
305	// unquotePath は、git が引用符で囲んで出したパス (日本語や " を含むもの。例: "\346\227\245.md") を元に戻す。
306	func unquotePath(s string) (string, error) {
307		if !strings.HasPrefix(s, `"`) {
308			return s, nil
309		}
310		u, err := strconv.Unquote(s)
311		if err != nil {
312			return "", fmt.Errorf("git blame の出力のファイル名を読めません: %s", s)
313		}
314		return u, nil
315	}
316	
317	func isZero(sha string) bool { return strings.Trim(sha, "0") == "" }
318	
319	func short(sha string) string {
320		if len(sha) > 12 {
321			return sha[:12]
322		}
323		return sha
324	}
