326	// gitRunner は、リポジトリのルートを基準に git を実行する。
327	type gitRunner struct{ root string }
328	
329	// toplevel は -root からリポジトリのルートを求める。入力の誤りにするのは、-root が存在する
330	// ディレクトリでないときと、-root から上のどこにも .git が無いときだけ。.git があるのに git が
331	// リポジトリとして読めない (権限・所有者など) ときは、渡し方では直せないので run-error にする。
332	// git は .git を読めないときも「not a git repository」と言うので、.git の有無は道具が確認する。
333	func toplevel(dir string) (string, error) {
334		if st, err := os.Stat(dir); err != nil || !st.IsDir() {
335			return "", inputf("-root が存在するディレクトリではありません: %s", dir)
336		}
337		out, _, err := gitRunner{root: dir}.run("rev-parse", "--show-toplevel")
338		if err == nil {
339			// 出力の末尾の改行 1 つだけを落とす。名前の末尾の空白はパスの一部なので削らない (削ると、空白の無い
340			// 名前の別のディレクトリを読む)
341			return strings.TrimSuffix(out, "\n"), nil
342		}
343		var re *runError
344		if errors.As(err, &re) {
345			return "", err
346		}
347		if strings.Contains(err.Error(), "not a git repository") {
348			if dotGit, ok := findDotGit(dir); ok {
349				return "", runf("%s があるが、git がリポジトリとして読めません: %v", dotGit, err)
350			}
351			return "", inputf("-root が git のリポジトリの中を指していません: %s", dir)
352		}
353		return "", runf("-root のリポジトリを git で読めません: %v", err)
354	}
355	
356	// findDotGit は、dir から上のディレクトリをたどって、最初に見つかった .git (ディレクトリか、
357	// 作業ツリーが持つファイル) のパスを返す。
358	func findDotGit(dir string) (string, bool) {
359		for d := filepath.Clean(dir); ; d = filepath.Dir(d) {
360			p := filepath.Join(d, ".git")
361			if _, err := os.Lstat(p); err == nil {
362				return p, true
363			}
364			if filepath.Dir(d) == d {
365				return "", false
366			}
367		}
368	}
