370	// run は git を実行し、標準出力と終了コードを返す。終了コードが 0 でなければ error も返す。
371	//
372	// どのディレクトリから実行しても同じ結果になるよう、git のオプション -C でルートを指定する。環境は関数 gitEnv が作る。
373	func (g gitRunner) run(args ...string) (string, int, error) {
374		return g.runIn(nil, args...)
375	}
