377	// gitTimeout は、git の 1 回の実行に許す時間。越えたら run-error にする。git や、git が起動する
378	// フィルタのプログラムが応答しなくなったときに、道具が終了しなくなるのを防ぐ。テストが短くする。
379	var gitTimeout = 5 * time.Minute
380	
381	// runIn は、stdin を標準入力に渡して run と同じように git を実行する。
382	//
383	// 設定 core.fsmonitor は打ち消す。打ち消さないと、git はそこに登録したプログラムを起動し、値が true なら
384	// 常駐のプロセス git fsmonitor--daemon が .git の下にファイルを作って、道具が終了した後も残る。
385	func (g gitRunner) runIn(stdin io.Reader, args ...string) (string, int, error) {
386		ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
387		defer cancel()
388		cmd := exec.CommandContext(ctx, "git", append([]string{"-C", g.root, "-c", "core.quotePath=false", "-c", "core.fsmonitor=false"}, args...)...)
389		cmd.WaitDelay = time.Second // 期限で停止させた git の子のプロセスが出力を開いたままでも、待機し続けない
390		cmd.Env = gitEnv()
391		cmd.Stdin = stdin
392		var stdout, stderr bytes.Buffer
393		cmd.Stdout, cmd.Stderr = &stdout, &stderr
394		err := cmd.Run()
395		if ctx.Err() == context.DeadlineExceeded {
396			return "", -1, runf("git %s が %s 以内に終了しませんでした", strings.Join(args, " "), gitTimeout)
397		}
398		if err == nil {
399			return stdout.String(), 0, nil
400		}
401		var exitErr *exec.ExitError
402		if errors.As(err, &exitErr) {
403			return stdout.String(), exitErr.ExitCode(), fmt.Errorf("git %s: %s", strings.Join(args, " "), strings.TrimSpace(stderr.String()))
404		}
405		return "", -1, runf("git を起動できません: %v", err)
406	}
