408	var gitVersionRe = regexp.MustCompile(`^git version ([0-9]+)\.([0-9]+)`)
409	
410	// checkGitVersion は、git を起動できることと、道具が要る版であることを確認する。要るのは 2.30 以降
411	// (関数 commit が使うコマンド git rev-parse --end-of-options が 2.30.0 から) で、フラグ -worktree では
412	// 2.41 以降 (関数 blame がコマンド git blame にオプション --contents と範囲 <起点>..<コミット> を一緒に
413	// 渡す形を、git は 2.41.0 から受け付ける)。古い git では、正しい版を渡しても解決できないか、git blame が
414	// 毎回失敗するので、入力の誤りと取り違えないよう、道具を実行できないこととして返す。
415	func checkGitVersion(worktree bool) error {
416		ctx, cancel := context.WithTimeout(context.Background(), gitTimeout)
417		defer cancel()
418		cmd := exec.CommandContext(ctx, "git", "version")
419		cmd.WaitDelay = time.Second
420		cmd.Env = gitEnv()
421		out, err := cmd.Output()
422		if ctx.Err() == context.DeadlineExceeded {
423			return runf("git version が %s 以内に終了しませんでした", gitTimeout)
424		}
425		if err != nil {
426			return runf("git を起動できません: %v", err)
427		}
428		major, minor, ok := parseGitVersion(string(out))
429		if !ok {
430			return runf("git の版を読めません: %s", strings.TrimSpace(string(out)))
431		}
432		if major < 2 || major == 2 && minor < 30 {
433			return runf("git 2.30 以降が要ります (git rev-parse --end-of-options を使うため)。この git は %s", strings.TrimSpace(string(out)))
434		}
435		if worktree && major == 2 && minor < 41 {
436			return runf("フラグ -worktree には git 2.41 以降が要ります (git blame に --contents と範囲を一緒に渡すため)。この git は %s", strings.TrimSpace(string(out)))
437		}
438		return nil
439	}
440	
441	func parseGitVersion(s string) (major, minor int, ok bool) {
442		m := gitVersionRe.FindStringSubmatch(strings.TrimSpace(s))
443		if m == nil {
444			return 0, 0, false
445		}
446		major, _ = strconv.Atoi(m[1])
447		minor, _ = strconv.Atoi(m[2])
448		return major, minor, true
449	}
