451	// extraGitEnv は、gitEnv が GIT_ で始まる変数を取り除いた後に足す変数。本番では空で、
452	// テストがシステムの git の設定を読ませないために使う (取り除く前に設定しても届かないため)。
453	var extraGitEnv []string
454	
455	// gitEnv は git に渡す環境を作る。利用者の環境の GIT_ で始まる変数は、リポジトリの場所を替える
456	// (GIT_DIR・GIT_WORK_TREE・GIT_INDEX_FILE など)、設定を注入する (GIT_CONFIG_PARAMETERS・
457	// GIT_CONFIG_COUNT など)、パスの読み方を替える (GIT_GLOB_PATHSPECS など) ので、-root と違う
458	// リポジトリや設定を読ませないよう、すべて取り除いてから道具が要るものだけを足す。
459	func gitEnv() []string {
460		var env []string
461		for _, kv := range os.Environ() {
462			if !strings.HasPrefix(kv, "GIT_") {
463				env = append(env, kv)
464			}
465		}
466		env = append(env,
467			// git の文言 (not a git repository など) を、利用者の言語の設定によらず英語にして比べられるようにする
468			"LC_ALL=C",
469			// パスを pathspec (パターンや先頭の : で始まる指定) として解釈させない
470			"GIT_LITERAL_PATHSPECS=1",
471			// コマンド git replace の置き換えを見ない。見ると、blame が置き換えた後の履歴で、行を最後に変えたコミットを求める
472			"GIT_NO_REPLACE_OBJECTS=1",
473			// 部分クローンで手元に無いオブジェクトを、ネットワークから取得してリポジトリに書き込まない (git 2.44 以降)。
474			// 取得できないと git は失敗し、道具は run-error になる
475			"GIT_NO_LAZY_FETCH=1",
476			// 認証などで利用者の入力待ちにならない
477			"GIT_TERMINAL_PROMPT=0",
478		)
479		return append(env, extraGitEnv...)
480	}
