482	// commit は版をコミットの完全な SHA に解決する。版が無いとき (オプション --quiet で終了コード 1) は
483	// found を false にする。それ以外の失敗 (リポジトリを読めない、など) は run-error。
484	func (g gitRunner) commit(rev string) (sha string, found bool, err error) {
485		out, code, err := g.run("rev-parse", "--verify", "--quiet", "--end-of-options", rev+"^{commit}")
486		switch {
487		case err == nil:
488			return strings.TrimSpace(out), true, nil
489		case code == 1:
490			return "", false, nil
491		default:
492			return "", false, asRun(err)
493		}
494	}
