508	// コミットの tree での、file のパスの項目の種類。
509	const (
510		entryNone    = "none"    // パスが無い
511		entryFile    = "file"    // 通常のファイル (100644・100755)
512		entrySymlink = "symlink" // シンボリックリンク (120000)
513		entryOther   = "other"   // ディレクトリ・サブモジュールなど、ファイルでないもの
514	)
515	
516	// modeKind は、コマンド git ls-files --stage が出す項目の mode を、項目の種類 (関数 entry の値) にする。
517	// 通常のファイルの mode は 100 で始まる (100644・100755)。
518	func modeKind(mode string) string {
519		switch {
520		case mode == "120000":
521			return entrySymlink
522		case strings.HasPrefix(mode, "100"):
523			return entryFile
524		default:
525			return entryOther
526		}
527	}
528	
529	// entry は、コミット commit の file のパスの項目の種類を返す。git が失敗したとき (オブジェクトを
530	// 読めない、など) は、パスが無いことと取り違えないよう run-error を返す。commit は解決済みの SHA。
531	func (g gitRunner) entry(commit, file string) (string, error) {
532		out, _, err := g.run("ls-tree", "-z", commit, "--", file)
533		if err != nil {
534			return "", asRun(err)
535		}
536		for _, e := range strings.Split(out, "\x00") {
537			meta, path, ok := strings.Cut(e, "\t")
538			if !ok || path != file {
539				continue
540			}
541			fields := strings.Fields(meta)
542			switch {
543			case len(fields) != 3 || fields[1] != "blob":
544				return entryOther, nil
545			case fields[0] == "120000":
546				return entrySymlink, nil
547			default:
548				return entryFile, nil
549			}
550		}
551		return entryNone, nil
552	}
