680	// blob は、コミット commit の file のブロブの SHA を返す。そのパスが無ければ空。
681	func (g gitRunner) blob(commit, file string) (string, error) {
682		out, code, err := g.run("rev-parse", "--verify", "--quiet", commit+":"+file)
683		switch {
684		case err == nil:
685			return strings.TrimSpace(out), nil
686		case code == 1:
687			return "", nil
688		default:
689			return "", err
690		}
691	}
