693	// blame は、範囲 <起点>..<コミット> で opts の行を最後に変えたコミットを求める。
694	// 範囲を起点で区切ると、起点から変わっていない行は起点が境界 (boundary) として報告される。
695	func (g gitRunner) blame(base, target string, opts options) ([]blameLine, error) {
696		args := []string{
697			"blame",
698			// 範囲の中のルートのコミット (無関係な履歴のマージ) を境界として扱わず、そのコミットの行として報告させる
699			"--root",
700			// 設定 blame.ignoreRevsFile に挙げたコミットを無視すると、そのコミットが書き換えた行が起点のままと報告される
701			"--ignore-revs-file", "",
702			// diff の textconv (比べる前にファイルを別の形へ変換する設定) で変換した行を比べると、
703			// 変換で消える部分だけを書き換えた行が、起点のままと報告される
704			"--no-textconv",
705			"--line-porcelain",
706		}
707		// 範囲はまとめてあるので、git blame はどの行も 1 回ずつ、ファイルの順に出す
708		want := 0
709		for _, r := range opts.ranges {
710			args = append(args, "-L", fmt.Sprintf("%d,%d", r.from, r.to))
711			want += r.to - r.from + 1
712		}
713		if opts.worktree {
714			args = append(args, "--contents", filepath.Join(g.root, filepath.FromSlash(opts.file)))
715		}
716		// 行がレビューした内容の行数を越えるのは渡し方の誤りなので、blame の前に道具が数えて
717		// input-error にする。blame そのものの失敗は、渡し方では説明できないので run-error にする
718		n, err := g.lineCount(target, opts)
719		if err != nil {
720			return nil, err
721		}
722		if err := checkLastLine(opts, n); err != nil {
723			return nil, err
724		}
725		args = append(args, base+".."+target, "--", opts.file)
726		out, _, err := g.run(args...)
727		if err != nil {
728			return nil, asRun(err)
729		}
730		lines, err := parsePorcelain(out)
731		if err != nil {
732			return nil, asRun(err)
733		}
734		if len(lines) != want {
735			return nil, runf("git blame が %d 行を返しました (求めたのは %d 行)", len(lines), want)
736		}
737		return lines, nil
738	}
